using System.Collections.Generic;
using UnityEngine;

namespace Kittehface;

public class PS5ActivitiesSinglePlayerStateManager : MonoBehaviour
{
	public enum ActivityState
	{
		None,
		NotStarted,
		Running,
		Ended
	}

	private class ActivityData
	{
		public bool available;

		public ActivityState activityState;

		public ActivityState previousActivityState;

		public PS5ActivitiesHelper.PS5ActivityOutcome activityOutcome;

		public bool needsOnlineAvailabilityUpdate;

		public bool needsOnlineStateUpdate;
	}

	private int userID = -1;

	private Dictionary<string, ActivityData> activities = new Dictionary<string, ActivityData>();

	private static PS5ActivitiesSinglePlayerStateManager instance;

	public static PS5ActivitiesSinglePlayerStateManager Instance
	{
		get
		{
			if (instance == null)
			{
				instance = new GameObject("PS5ActivitiesSinglePlayerStateManager").AddComponent<PS5ActivitiesSinglePlayerStateManager>();
			}
			return instance;
		}
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
		}
		else if (instance != this)
		{
			Object.Destroy(base.gameObject);
			return;
		}
		Object.DontDestroyOnLoad(base.gameObject);
	}

	public static void InitializeAfterSaveDataLoad(int userID)
	{
		Debug.Log("PS5ActivitiesSinglePlayerStateManager.InitializeAfterSaveDataLoad");
		Instance.activities.Clear();
		Instance.userID = userID;
		PS5ActivitiesHelper.TerminateActivities(Instance.userID);
	}

	public static void AddActivity(string activityID, bool available, ActivityState initialActivityState, bool allowOnlineUpdate = true)
	{
		Debug.LogFormat("PS5ActivitiesSinglePlayerStateManager.AddActivity({0}, {1}, {2}, {3})", activityID, available, initialActivityState, allowOnlineUpdate);
		if (string.IsNullOrEmpty(activityID) || initialActivityState == ActivityState.None)
		{
			return;
		}
		bool flag = false;
		if (Instance.activities.ContainsKey(activityID))
		{
			flag = true;
			if (activityID == PS5ActivitiesHelper.MainActivityID && Instance.activities[activityID].previousActivityState == ActivityState.None && Instance.activities[activityID].activityState == ActivityState.None)
			{
				flag = false;
			}
		}
		if (!flag)
		{
			if (Instance.activities.ContainsKey(activityID))
			{
				Instance.activities[activityID].available = available;
				Instance.activities[activityID].needsOnlineAvailabilityUpdate = true;
				Instance.activities[activityID].previousActivityState = initialActivityState;
			}
			else
			{
				ActivityData activityData = new ActivityData();
				activityData.available = available;
				activityData.needsOnlineAvailabilityUpdate = true;
				activityData.previousActivityState = initialActivityState;
				Instance.activities.Add(activityID, activityData);
			}
			if (allowOnlineUpdate)
			{
				UpdateActivityStatesOnline();
			}
		}
	}

	public static void SetActivityState(string activityID, bool available, ActivityState activityState, PS5ActivitiesHelper.PS5ActivityOutcome activityOutcome = PS5ActivitiesHelper.PS5ActivityOutcome.Completed, bool allowOnlineUpdate = true)
	{
		Debug.LogFormat("SetActivityState.SetActivityState({0}, {1}, {2}, {3}, {4})", activityID, available, activityState, activityOutcome, allowOnlineUpdate);
		if (string.IsNullOrEmpty(activityID) || !Instance.activities.ContainsKey(activityID))
		{
			return;
		}
		ActivityData activityData = Instance.activities[activityID];
		bool flag = false;
		bool flag2 = false;
		if (available != activityData.available)
		{
			activityData.available = available;
			flag = true;
		}
		if (activityState != activityData.activityState && activityState != 0)
		{
			if (activityData.activityState != 0)
			{
				activityData.previousActivityState = activityData.activityState;
			}
			activityData.activityState = activityState;
			flag2 = true;
		}
		activityData.activityOutcome = activityOutcome;
		activityData.needsOnlineAvailabilityUpdate |= flag;
		activityData.needsOnlineStateUpdate |= flag2;
		if (allowOnlineUpdate)
		{
			UpdateActivityStatesOnline();
		}
	}

	public static bool IsActivityAvailable(string activityID)
	{
		if (Instance.activities.ContainsKey(activityID))
		{
			return Instance.activities[activityID].available;
		}
		return false;
	}

	public static ActivityState GetActivityState(string activityID)
	{
		if (Instance.activities.ContainsKey(activityID))
		{
			return Instance.activities[activityID].activityState;
		}
		return ActivityState.None;
	}

	public static void UpdateActivityStatesOnline(bool forceUpdate = false)
	{
		Debug.LogFormat("PS5ActivitiesSinglePlayerStateManager.UpdateActivityStatesOnline({0})", forceUpdate);
		List<string> list = null;
		List<string> list2 = null;
		foreach (KeyValuePair<string, ActivityData> activity in Instance.activities)
		{
			string key = activity.Key;
			ActivityData value = activity.Value;
			if (value.needsOnlineAvailabilityUpdate || forceUpdate)
			{
				if (value.available)
				{
					if (list == null)
					{
						list = new List<string>();
					}
					list.Add(key);
				}
				else
				{
					if (list2 == null)
					{
						list2 = new List<string>();
					}
					list2.Add(key);
				}
				value.needsOnlineAvailabilityUpdate = false;
			}
			if (!(value.needsOnlineStateUpdate || forceUpdate))
			{
				continue;
			}
			Debug.LogFormat("PS5ActivitiesSinglePlayerStateManager.UpdateActivityStatesOnline: update activity [{0}], current state [{1}], previous state [{2}]", key, value.activityState, value.previousActivityState);
			if (value.activityState == ActivityState.Running)
			{
				if (value.previousActivityState == ActivityState.NotStarted || value.previousActivityState == ActivityState.Ended)
				{
					PS5ActivitiesHelper.StartActivity(Instance.userID, key);
				}
				else
				{
					PS5ActivitiesHelper.ResumeActivity(Instance.userID, key);
				}
			}
			else if (value.activityState == ActivityState.Ended && value.previousActivityState != ActivityState.Ended)
			{
				PS5ActivitiesHelper.EndActivity(Instance.userID, key, value.activityOutcome);
			}
			value.needsOnlineStateUpdate = false;
		}
		if (list != null || list2 != null)
		{
			PS5ActivitiesHelper.UpdateActivityAvailability(Instance.userID, list, list2);
		}
	}
}
